1	//! Format — current multi-file CSV; round-trip structure.analysis.* and
2	//! structure.definition.* ↔ CSV.
3	
4	use anyhow::Result;
5	use std::collections::{BTreeMap, BTreeSet};
6	use std::path::Path;
7	
8	use crate::structure::analysis::attractors::Attractor;
9	use crate::structure::analysis::force::{Force, ForceKind};
10	use crate::structure::analysis::residues::Residue;
11	use crate::structure::definition::lexicon::Term;
12	
13	const FORCES_HEADER: &str = "id,kind,shortname,naive_change,outcomes,description,attractor_id";
14	const LEXICON_HEADER: &str = "term,definition,domain,aliases";
15	const RESIDUES_MATRIX_FORCE_COL: &str = "force";
16	const ATTRACTORS_V3_HEADER: &str = "id,name,description,positive_state,negative_state";
17	
18	pub fn write_forces(residual_dir: &Path, forces: &[Force]) -> Result<()> {
19	    let path = residual_dir.join("forces.csv");
20	    let mut buf = FORCES_HEADER.to_string();
21	    buf.push('\n');
22	    for f in forces {
23	        let kind = match f.kind {
24	            ForceKind::Purpose => "purpose",
25	            ForceKind::Stressor => "stressor",
26	        };
27	        let outcomes = f.outcomes.join("|");
28	        let mut row = Vec::new();
29	        {
30	            let mut wtr = csv::WriterBuilder::new()
31	                .has_headers(false)
32	                .from_writer(&mut row);
33	            wtr.write_record(&[
34	                f.id.as_str(),
35	                kind,
36	                f.shortname.as_str(),
37	                f.naive_change.as_str(),
38	                outcomes.as_str(),
39	                f.description.as_str(),
40	                f.attractor_id.as_str(),
41	            ])?;
42	            wtr.flush()?;
43	        }
44	        buf.push_str(std::str::from_utf8(&row)?);
45	    }
46	    std::fs::write(path, buf)?;
47	    Ok(())
48	}
49	
50	pub fn read_forces(residual_dir: &Path) -> Result<Vec<Force>> {
51	    let path = residual_dir.join("forces.csv");
52	    if !path.exists() {
53	        return Ok(vec![]);
54	    }
55	    let mut rdr = csv::ReaderBuilder::new()
56	        .has_headers(true)
57	        .from_path(&path)?;
58	    let mut out = Vec::new();
59	    for rec in rdr.records() {
60	        let rec = rec?;
61	        let kind = match rec.get(1).unwrap_or("").to_lowercase().as_str() {
62	            "purpose" => ForceKind::Purpose,
63	            _ => ForceKind::Stressor,
64	        };
65	        let outcomes = rec
66	            .get(4)
67	            .unwrap_or("")
68	            .split('|')
69	            .filter(|s| !s.is_empty())
70	            .map(|s| s.to_string())
71	            .collect();
72	        out.push(Force {
73	            id: rec.get(0).unwrap_or("").to_string(),
74	            kind,
75	            shortname: rec.get(2).unwrap_or("").to_string(),
76	            naive_change: rec.get(3).unwrap_or("").to_string(),
77	            outcomes,
78	            description: rec.get(5).unwrap_or("").to_string(),
79	            attractor_id: rec.get(6).unwrap_or("").to_string(),
80	        });
81	    }
82	    Ok(out)
83	}
