109	pub fn read_lexicon(residual_dir: &Path) -> Result<Vec<Term>> {
110	    let path = residual_dir.join("lexicon.csv");
111	    if !path.exists() {
112	        return Ok(vec![]);
113	    }
114	    let mut rdr = csv::ReaderBuilder::new()
115	        .has_headers(true)
116	        .from_path(&path)?;
117	    let mut out = Vec::new();
118	    for rec in rdr.deserialize() {
