124	fn parse_residue_cell(cell: &str) -> (String, String) {
125	    if let Some((status, notes)) = cell.split_once('|') {
126	        (status.trim().to_string(), notes.trim().to_string())
127	    } else {
128	        (cell.trim().to_string(), String::new())
129	    }
130	}
131	
132	fn format_residue_cell(status: &str, notes: &str) -> String {
133	    if notes.is_empty() {
134	        status.to_string()
135	    } else {
136	        format!("{status}|{notes}")
137	    }
138	}
139	
140	fn residues_is_matrix_header(header: &str) -> bool {
141	    header
142	        .split(',')
143	        .next()
144	        .map(|c| c.trim().eq_ignore_ascii_case(RESIDUES_MATRIX_FORCE_COL))
145	        .unwrap_or(false)
146	}
147	
148	fn residues_to_rows(
149	    residues: &[Residue],
150	) -> (
151	    Vec<String>,
152	    BTreeMap<String, BTreeMap<String, (String, String)>>,
153	) {
154	    let mut components = BTreeSet::new();
155	    let mut cells: BTreeMap<String, BTreeMap<String, (String, String)>> = BTreeMap::new();
156	    for r in residues {
157	        if r.force_id.is_empty() || r.component_id.is_empty() {
158	            continue;
159	        }
160	        components.insert(r.component_id.clone());
161	        cells
162	            .entry(r.force_id.clone())
163	            .or_default()
164	            .insert(r.component_id.clone(), (r.status.clone(), r.notes.clone()));
165	    }
166	    (components.into_iter().collect(), cells)
167	}
168	
169	fn render_residues_matrix(residues: &[Residue]) -> String {
170	    let (components, cells) = residues_to_rows(residues);
171	    let mut buf = RESIDUES_MATRIX_FORCE_COL.to_string();
172	    for c in &components {
173	        buf.push(',');
174	        buf.push_str(c);
175	    }
176	    buf.push('\n');
177	    for force_id in cells.keys() {
178	        let force_cells = cells.get(force_id).unwrap();
179	        let mut row = vec![force_id.as_str()];
180	        let mut cell_values = Vec::new();
181	        for c in &components {
182	            cell_values.push(
183	                force_cells
184	                    .get(c)
185	                    .map(|(s, n)| format_residue_cell(s, n))
186	                    .unwrap_or_default(),
187	            );
188	        }
189	        for v in &cell_values {
190	            row.push(v.as_str());
191	        }
192	        let mut out = Vec::new();
193	        {
194	            let mut wtr = csv::WriterBuilder::new()
195	                .has_headers(false)
196	                .from_writer(&mut out);
197	            wtr.write_record(&row).unwrap();
198	            wtr.flush().unwrap();
199	        }
200	        buf.push_str(std::str::from_utf8(&out).unwrap());
201	    }
202	    buf
203	}
204	
205	pub fn format_residues_matrix(residual_dir: &Path) -> Result<String> {
206	    Ok(render_residues_matrix(&read_residues(residual_dir)?))
207	}
208	
209	pub fn write_residues(residual_dir: &Path, residues: &[Residue]) -> Result<()> {
210	    std::fs::write(
211	        residual_dir.join("residues.csv"),
212	        render_residues_matrix(residues),
213	    )?;
214	    Ok(())
215	}
216	
217	pub fn read_residues(residual_dir: &Path) -> Result<Vec<Residue>> {
218	    let path = residual_dir.join("residues.csv");
219	    if !path.exists() {
220	        return Ok(vec![]);
221	    }
222	    let text = std::fs::read_to_string(&path)?;
223	    let mut lines = text.lines();
224	    let header = lines.next().unwrap_or("");
225	    if header.trim().is_empty() {
226	        return Ok(vec![]);
227	    }
228	    if residues_is_matrix_header(header) {
229	        return read_residues_matrix(header, lines);
230	    }
231	    read_residues_legacy(&path)
232	}
233	
234	fn read_residues_matrix<'a, I>(header: &str, rows: I) -> Result<Vec<Residue>>
235	where
236	    I: Iterator<Item = &'a str>,
237	{
238	    let components: Vec<String> = header
239	        .split(',')
240	        .skip(1)
241	        .map(|s| s.trim().to_string())
242	        .filter(|s| !s.is_empty())
243	        .collect();
244	    let mut out = Vec::new();
245	    let mut id_n = 0u32;
246	    for line in rows {
247	        if line.trim().is_empty() {
248	            continue;
249	        }
250	        let mut rdr = csv::ReaderBuilder::new()
251	            .has_headers(false)
252	            .from_reader(line.as_bytes());
253	        let rec = rdr.records().next().transpose()?.unwrap_or_default();
254	        let force_id = rec.get(0).unwrap_or("").trim().to_string();
255	        if force_id.is_empty() {
256	            continue;
257	        }
258	        for (i, component_id) in components.iter().enumerate() {
259	            let cell = rec.get(i + 1).unwrap_or("").trim();
260	            if cell.is_empty() {
261	                continue;
262	            }
263	            id_n += 1;
264	            let (status, notes) = parse_residue_cell(cell);
265	            out.push(Residue {
266	                id: format!("R-{id_n:02}"),
267	                force_id: force_id.clone(),
268	                component_id: component_id.clone(),
269	                status,
270	                notes,
271	            });
272	        }
273	    }
274	    Ok(out)
275	}
