1	use anyhow::{bail, Result};
2	use std::time::{Duration, Instant};
3	use crate::config::Config;
4	use crate::cli::VerifyCheck;
5	
6	pub const OUTCOME_VERIFY_SLOW_SECS: u64 = 2;
7	
8	pub fn slow_outcome_verify_warning(elapsed: Duration) -> Option<String> {
9	    if elapsed.as_secs() >= OUTCOME_VERIFY_SLOW_SECS {
10	        Some(format!(
11	            "WARN: outcome validation took {:.2}s (≥{}s) — slow verify may drive hook bypass (S-06)",
12	            elapsed.as_secs_f64(),
13	            OUTCOME_VERIFY_SLOW_SECS
14	        ))
15	    } else {
16	        None
17	    }
18	}
19	
20	fn print_slow_outcome_warning(elapsed: Duration) {
21	    if let Some(warn) = slow_outcome_verify_warning(elapsed) {
22	        println!("{warn}");
23	    }
24	}
25	
26	pub fn run(cfg: &Config, check: VerifyCheck) -> Result<()> {
27	    match check {
28	        VerifyCheck::Outcomes => {
29	            let started = Instant::now();
30	            let violations = check_outcomes(cfg)?;
31	            print_slow_outcome_warning(started.elapsed());
32	            if violations.is_empty() {
33	                println!("OK: all outcomes reference at least one terminology term.");
34	            } else {
35	                for v in &violations {
36	                    println!("VIOLATION [{}] {}: {} — {}", v.source, v.id, v.outcome_str, v.reason);
37	                }
38	                bail!("{} outcome violation(s) found.", violations.len());
39	            }
40	        }
41	        VerifyCheck::Links => {
42	            let violations = check_links(cfg)?;
43	            if violations.is_empty() {
44	                println!("OK: all attractor links are valid.");
45	            } else {
46	                for v in &violations {
47	                    println!("VIOLATION [{}] {}: {}", v.source, v.id, v.message);
48	                }
49	                bail!("{} link violation(s) found.", violations.len());
50	            }
51	        }
52	        VerifyCheck::All => {
53	            let started = Instant::now();
54	            let outcome_violations = check_outcomes(cfg)?;
55	            print_slow_outcome_warning(started.elapsed());
56	            let link_violations = check_links(cfg)?;
57	            let total = outcome_violations.len() + link_violations.len();
58	            for v in &outcome_violations {
59	                println!("OUTCOME VIOLATION [{}] {}: {} — {}", v.source, v.id, v.outcome_str, v.reason);
60	            }
61	            for v in &link_violations {
62	                println!("LINK VIOLATION [{}] {}: {}", v.source, v.id, v.message);
63	            }
64	            if total == 0 {
65	                println!("OK: all checks passed.");
66	            } else {
67	                bail!("{} total violation(s) found.", total);
68	            }
69	        }
70	        VerifyCheck::CommitMsg { .. } => {
71	            anyhow::bail!("verify commit-msg is handled by the CLI dispatcher; call residual verify commit-msg directly");
72	        }
73	    }
74	    Ok(())
75	}
