77	pub fn check_outcomes(cfg: &Config) -> Result<Vec<OutcomeViolation>> {
78	    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
79	    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
80	    let term_index = crate::storage::terminology::term_index(&cfg.residual_dir)?;
81	
82	    let mut violations = Vec::new();
83	
84	    for stressor in &stressors {
85	        for raw_outcome in stressor.outcomes.split('|') {
86	            let raw_outcome = raw_outcome.trim();
87	            if raw_outcome.is_empty() {
88	                continue;
89	            }
90	            match parse_outcome(raw_outcome) {
91	                None => {
92	                    violations.push(OutcomeViolation {
93	                        source: "stressor".to_string(),
94	                        id: stressor.id.clone(),
95	                        outcome_str: raw_outcome.to_string(),
96	                        reason: "outcome must have at least subject verb predicate (3 words)".to_string(),
97	                    });
98	                }
99	                Some(parts) => {
100	                    if !outcome_uses_terminology(raw_outcome, &parts, &term_index) {
101	                        violations.push(OutcomeViolation {
102	                            source: "stressor".to_string(),
103	                            id: stressor.id.clone(),
104	                            outcome_str: raw_outcome.to_string(),
105	                            reason: "no word in this outcome matches the project terminology".to_string(),
106	                        });
107	                    }
108	                }
109	            }
110	        }
111	    }
112	
113	    for purpose in &purposes {
114	        for raw_outcome in purpose.outcomes.split('|') {
115	            let raw_outcome = raw_outcome.trim();
116	            if raw_outcome.is_empty() {
117	                continue;
118	            }
119	            match parse_outcome(raw_outcome) {
120	                None => {
121	                    violations.push(OutcomeViolation {
122	                        source: "purpose".to_string(),
123	                        id: purpose.id.clone(),
124	                        outcome_str: raw_outcome.to_string(),
125	                        reason: "outcome must have at least subject verb predicate (3 words)".to_string(),
126	                    });
127	                }
128	                Some(parts) => {
129	                    if !outcome_uses_terminology(raw_outcome, &parts, &term_index) {
130	                        violations.push(OutcomeViolation {
131	                            source: "purpose".to_string(),
132	                            id: purpose.id.clone(),
133	                            outcome_str: raw_outcome.to_string(),
134	                            reason: "no word in this outcome matches the project terminology".to_string(),
135	                        });
136	                    }
137	                }
138	            }
139	        }
140	    }
141	
142	    Ok(violations)
143	}
144	
145	pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
146	    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
147	    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
148	    let attractors = crate::storage::attractors::load(&cfg.residual_dir)?;
149	    let attractor_ids: std::collections::HashSet<String> =
150	        attractors.iter().map(|a| a.id.clone()).collect();
151	
152	    let mut violations = Vec::new();
153	
154	    for stressor in &stressors {
155	        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
156	            violations.push(LinkViolation {
157	                source: "stressor".to_string(),
158	                id: stressor.id.clone(),
159	                message: format!("missing attractor '{}'", stressor.attractor_id),
160	            });
161	        }
162	    }
163	
164	    for purpose in &purposes {
165	        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
166	            violations.push(LinkViolation {
167	                source: "purpose".to_string(),
168	                id: purpose.id.clone(),
169	                message: format!("missing attractor '{}'", purpose.attractor_id),
170	            });
171	        }
172	    }
173	
174	    let forces = crate::storage::format::read_forces(&cfg.residual_dir)?;
175	    let residues = crate::storage::format::read_residues(&cfg.residual_dir)?;
176	    let registry = crate::structure::definition::components::load(&cfg.residual_dir)?;
177	    let mut force_ids = std::collections::HashSet::new();
178	    for s in &stressors {
179	        force_ids.insert(s.id.clone());
180	    }
181	    for p in &purposes {
182	        force_ids.insert(p.id.clone());
183	    }
184	    for f in &forces {
185	        force_ids.insert(f.id.clone());
186	    }
187	    let component_names: std::collections::HashSet<String> =
188	        registry.iter().map(|c| c.name.clone()).collect();
189	
190	    for force in &forces {
191	        if !force.attractor_id.is_empty() && !attractor_ids.contains(&force.attractor_id) {
192	            violations.push(LinkViolation {
193	                source: "force".to_string(),
194	                id: force.id.clone(),
195	                message: format!("missing attractor '{}'", force.attractor_id),
196	            });
197	        }
198	    }
199	
200	    for residue in &residues {
201	        if !residue.force_id.is_empty() && !force_ids.contains(&residue.force_id) {
202	            violations.push(LinkViolation {
203	                source: "residue".to_string(),
204	                id: residue.id.clone(),
205	                message: format!("force_id '{}' not found", residue.force_id),
206	            });
207	        }
208	        // whole-system-residue uses a virtual component outside the registry (A-07).
209	        if crate::structure::analysis::residues::is_whole_system_residue(residue) {
210	            continue;
211	        }
212	        if !residue.component_id.is_empty() && !component_names.contains(&residue.component_id) {
213	            violations.push(LinkViolation {
214	                source: "residue".to_string(),
215	                id: residue.id.clone(),
216	                message: format!(
217	                    "component_id '{}' not found in components.csv",
218	                    residue.component_id
219	                ),
220	            });
221	        }
222	    }
223	
224	    Ok(violations)
225	}
