227	pub fn parse_outcome(outcome_str: &str) -> Option<OutcomeParts> {
228	    let words: Vec<&str> = outcome_str.split_whitespace().collect();
229	    if words.len() < 3 {
230	        return None;
231	    }
232	    let subject = words[0].to_string();
233	    let verb = words[1].to_string();
234	    let predicate = words[2..].join(" ");
235	    Some(OutcomeParts {
236	        subject,
237	        verb,
238	        predicates: vec![predicate],
239	    })
240	}
241	
242	pub struct OutcomeParts {
243	    pub subject: String,
244	    pub verb: String,
245	    pub predicates: Vec<String>,
246	}
247	
248	pub struct OutcomeViolation {
249	    pub source: String,
250	    pub id: String,
251	    pub outcome_str: String,
252	    pub reason: String,
253	}
254	
255	pub struct LinkViolation {
256	    pub source: String,
257	    pub id: String,
258	    pub message: String,
259	}
260	
261	/// Check if any word or phrase in the outcome touches the terminology index.
262	pub fn outcome_uses_terminology(
263	    outcome_str: &str,
264	    parts: &OutcomeParts,
265	    index: &crate::storage::terminology::TermIndex,
266	) -> bool {
267	    if index.words.contains(&parts.subject.to_lowercase()) {
268	        return true;
269	    }
270	    if index.words.contains(&parts.verb.to_lowercase()) {
271	        return true;
272	    }
273	    for predicate in &parts.predicates {
274	        for word in predicate.split_whitespace() {
275	            if index.words.contains(&word.to_lowercase()) {
276	                return true;
277	            }
278	        }
279	    }
280	    let lower = outcome_str.to_lowercase();
281	    for phrase in &index.phrases {
282	        if phrase.len() >= 3 && lower.contains(phrase.as_str()) {
283	            return true;
284	        }
285	    }
286	    false
287	}
