        }
        for v in &cell_values {
            row.push(v.as_str());
        }
        let mut out = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new()
                .has_headers(false)
                .from_writer(&mut out);
            wtr.write_record(&row).unwrap();
            wtr.flush().unwrap();
        }
        buf.push_str(std::str::from_utf8(&out).unwrap());
    }
    buf
}

