use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Stressor {
    pub id: String,
    pub description: String,
    pub attractor_id: String,
    pub naive_change: String,
    #[serde(rename = "outcomes", alias = "traits")]
    pub outcomes: String,
    pub components_affected: String,
}

pub fn load(residual_dir: &Path) -> Result<Vec<Stressor>> {
    let path = residual_dir.join("stressors.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_path(&path)?;
    let mut result = Vec::new();
    for record in rdr.deserialize() {
        let s: Stressor = record?;
        result.push(s);
    }
    Ok(result)
}

pub fn append(residual_dir: &Path, stressor: Stressor) -> Result<()> {
    let mut all = load(residual_dir)?;
    if all.iter().any(|s| s.id == stressor.id) {
        anyhow::bail!("stressor id '{}' already exists", stressor.id);
    }
    all.push(stressor);
    write_all(residual_dir, &all)
}

fn write_all(residual_dir: &Path, rows: &[Stressor]) -> Result<()> {
    let mut buf = String::from("id,description,naive_change,outcomes,components_affected,attractor_id\n");
    for s in rows {
        let mut row = Vec::new();
        {
            let mut wtr = csv::WriterBuilder::new().has_headers(false).from_writer(&mut row);
            wtr.write_record(&[
                &s.id,
                &s.description,
                &s.naive_change,
                &s.outcomes,
                &s.components_affected,
                &s.attractor_id,
            ])?;
            wtr.flush()?;
        }
        buf.push_str(std::str::from_utf8(&row)?);
    }
    std::fs::write(residual_dir.join("stressors.csv"), buf)?;
    Ok(())
}

pub fn next_id(stressors: &[Stressor]) -> String {
    let max = stressors
        .iter()
        .filter_map(|s| {
            s.id.strip_prefix("S-").and_then(|n| n.parse::<u32>().ok())
        })
        .max()
        .unwrap_or(0);
    format!("S-{:02}", max + 1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    fn make_stressor(id: &str) -> Stressor {
        Stressor {
            id: id.to_string(),
            description: "desc".to_string(),
            attractor_id: "A-01".to_string(),
            naive_change: "change".to_string(),
            outcomes: "system handles auth".to_string(),
            components_affected: "auth,db".to_string(),
        }
    }

    #[test]
    fn next_id_empty() {
        assert_eq!(next_id(&[]), "S-01");
    }

    #[test]
    fn next_id_after_s03() {
        let stressors = vec![make_stressor("S-01"), make_stressor("S-03")];
        assert_eq!(next_id(&stressors), "S-04");
    }

    #[test]
    fn append_creates_file_with_header_and_row() {
        let dir = tempdir().unwrap();
        let s = make_stressor("S-01");
        append(dir.path(), s).unwrap();
        let content = std::fs::read_to_string(dir.path().join("stressors.csv")).unwrap();
        assert!(content.contains("id,"), "header missing");
        assert!(content.contains("S-01"), "row missing");
    }

    #[test]
    fn append_does_not_duplicate_header() {
        let dir = tempdir().unwrap();
        append(dir.path(), make_stressor("S-01")).unwrap();
        append(dir.path(), make_stressor("S-02")).unwrap();
        let content = std::fs::read_to_string(dir.path().join("stressors.csv")).unwrap();
        assert_eq!(content.matches("id,").count(), 1, "header duplicated");
    }

    #[test]
    fn load_reads_back_appended() {
        let dir = tempdir().unwrap();
        append(dir.path(), make_stressor("S-01")).unwrap();
        let loaded = load(dir.path()).unwrap();
        assert_eq!(loaded.len(), 1);
        assert_eq!(loaded[0].id, "S-01");
    }

    #[test]
    fn append_rejects_duplicate_id() {
        let dir = tempdir().unwrap();
        append(dir.path(), make_stressor("S-01")).unwrap();
        let err = append(dir.path(), make_stressor("S-01")).unwrap_err();
        assert!(err.to_string().contains("already exists"));
    }

    #[test]
    fn load_missing_file_returns_empty() {
        let dir = tempdir().unwrap();
        let result = load(dir.path()).unwrap();
        assert!(result.is_empty());
    }
}

use anyhow::Result;
use clap::{Parser, Subcommand};

pub mod help;

#[derive(Parser)]
#[command(name = "residual", about = "NKP Residuality architecture CLI", version)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

#[derive(Subcommand)]
pub enum Command {
    /// Initialize residual/ in the current project.
    ///
    /// Process: idempotent bootstrap — create residual/ CSVs and v3 config
    /// without overwriting existing data. Add attractors before forces.
    Init {
        /// Overwrite session snapshot when residual files drifted outside this tool.
        #[arg(long)]
        force: bool,
    },
    /// Add a residual record.
    ///
    /// Process: examine whole-system-residue before a software-only patch.
    /// Forces carry outcomes, not component lists; map components via residues.
    /// Prefer adding a force (purpose XOR stressor) then a residue mapping.
    Add {
        /// Overwrite session snapshot when residual files drifted outside this tool.
        #[arg(long)]
        force: bool,
        #[command(subcommand)]
        target: AddTarget,
    },
    /// List residual records (filter/group by attractor; not creation order).
    List {
        #[command(subcommand)]
        target: ListTarget,
    },
    /// Verify residual integrity.
    ///
    /// Process: one-way tags (code tags must exist in metadata; metadata-only is
    /// OK). Walks require at least two personas until alpha/beta exist.
    /// Policy (super_strict, token_warn, commit_msg_enforce) is read from storage-config.
    Verify {
        #[command(subcommand)]
        check: VerifyCheck,
    },
    /// Compose or check commit messages using project vocabulary.
    ///
    /// Process: subjects must use lexicon terms, component names, force prefixes,
    /// or start with `general - `. Body is always free-form.
    Commit {
        #[command(subcommand)]
        op: CommitOp,
    },
    /// NKP matrix operations (structure-analysis).
    ///
    /// Process: filter/group by attractor when reading; do not assume creation order.
    Matrix {
        #[command(subcommand)]
        op: MatrixOp,
    },
    /// Phase + installer skills.
    ///
    /// Process: a-la-carte — only the invoked subcommand carries ceremony.
    /// Use `skill install all` or `--agent all` to batch-install.
    Skill {
        #[command(subcommand)]
        op: SkillCommand,
    },
    Tag {
        #[command(subcommand)]
        op: TagOp,
    },
    /// Generate help artifacts (completions/man) or the verification git hook.
    Generate {
        #[command(subcommand)]
        artifact: GenerateArtifact,
    },
    /// Migrate residual/ from naive on-disk shape to v3.
    ///
    /// Process: config → storage-config; stressors/purposes → forces+residues;
    /// attractors valence → +/- states; terminology → lexicon. Legacy force CSVs
    /// remain for mid-transition readers.
    Migrate {
        /// Overwrite session snapshot when residual files drifted outside this tool.
        #[arg(long)]
        force: bool,
    },
    Config,
}

#[derive(Subcommand)]
pub enum SkillCommand {
    /// Show an embedded phase skill definition.
    ///
    /// Process: read the skill a-la-carte; unused phase ceremony is not loaded.
    Show {

    Show {
        name: String,
        #[arg(long)]
        version: bool,
    },
    /// Print residual context for a phase skill.
    ///
    /// Process: load only the data that phase needs. Walks that use personas
    /// require min:2 (Verification).
    Data { name: String },
    /// List phase skills (stub + full) with token estimates.
    List,
    /// Install a phase skill into an agent directory.
    ///
    /// Pass `all` as the skill name to install every skill.
    /// Pass `--agent all` to install for every supported agent.
    Install {
        /// Skill name, or `all` to install every skill.
        name: String,
        /// Agent name (`claude`, `cursor`, `copilot`, `agnostic`), or `all`.
        #[arg(long, default_value = "agnostic")]
        agent: String,
        #[arg(long)]
        global: bool,
    },
    /// Check whether an installed skill matches the embedded version.
    ///
    /// Process: compare installed front-matter version to the binary. Prefer
    /// this name over legacy `skill-check`.
    CheckInstall {
        name: String,
        #[arg(long, default_value = "agnostic")]
        agent: String,
    },
}

#[derive(Subcommand)]
pub enum AddTarget {
    /// Add a stressor force. Process: whole-system-residue first — record outcomes.
    Stressor {
        #[arg(long)] description: String,
        #[arg(long)] attractor_id: String,
        #[arg(long)] naive_change: String,
        #[arg(long, default_value = "", visible_alias = "traits")]
        outcomes: String,
        #[arg(long, default_value = "")] components: String,
        #[arg(long)]
        whole_system: bool,
        #[arg(long, default_value = "")]
        notes: String,
    },
    /// Add a residue mapping. Process: whole-system-residue first for non-software zig.
    Residue {
        #[arg(long)] force_id: String,
        #[arg(long, default_value = "")] component_id: String,
        #[arg(long, default_value = "proposed")] status: String,
        #[arg(long, default_value = "")] notes: String,
        #[arg(long)]
        whole_system: bool,
    },
    /// Add a purpose force. Process: whole-system-residue first — record outcomes.
    Purpose {
        #[arg(long)] description: String,
        #[arg(long)] attractor_id: String,
        #[arg(long, visible_alias = "naive-change")]
        feature: String,
        #[arg(long, default_value = "", visible_alias = "traits")]
        outcomes: String,
        #[arg(long, default_value = "")] components: String,
    },
    Attractor {
        #[arg(long)] name: String,
        #[arg(long)] description: String,
        #[arg(long)] positive_state: String,
        #[arg(long)] negative_state: String,
    },
    Term {
        #[arg(long)] term: String,
        #[arg(long)] definition: String,
        #[arg(long, default_value = "")] domain: String,
        #[arg(long, default_value = "")] related: String,
    },
    Persona {
        #[arg(long)] name: String,
        #[arg(long)] role: String,
        #[arg(long, default_value = "")] concerns: String,
        #[arg(long, default_value = "")] desires: String,
    },
    Iteration {
        #[arg(long, default_value = "")] notes: String,
        #[arg(long, default_value = "")] ri_score: String,
    },
}

#[derive(Subcommand)]
pub enum ListTarget {
    Stressors,
    Purposes,
    Attractors,
    Terminology,
    Personas,
    Iterations,
    Residues,
}

#[derive(Subcommand)]
pub enum VerifyCheck {
    /// Verify purpose/stressor outcome statements reference terminology.
    #[command(name = "outcomes", visible_aliases = ["traits"])]
    Outcomes,
    Links,
    All,
    /// Validate a git commit message subject against lexicon/components.
    CommitMsg {
        /// Path to the commit message file (first line = subject).
        #[arg(value_name = "FILE")]
        file: Option<String>,
        /// Message text instead of a file.
        #[arg(short, long)]
        message: Option<String>,
        /// Block on violations (overrides storage-config commit_msg_enforce).
        #[arg(long)]
        enforce: bool,
        /// Warn only, never block (overrides storage-config).
        #[arg(long)]
        warn: bool,
        /// Read staged paths for component hints.
        #[arg(long)]
        staged: bool,
    },
}

#[derive(Subcommand)]
pub enum CommitOp {
    /// Dry-run commit-msg validation.
    Check {
        #[arg(short, long)]
        message: String,
        #[arg(long)]
        enforce: bool,
        #[arg(long)]
        warn: bool,
        #[arg(long)]
        staged: bool,
    },
    /// Suggest subjects from staged diff and open residues.
    Suggest {
        #[arg(long)]
        staged: bool,
    },
